// O(1) lookup index map by 3-letter IATA code
export const AIRPORT_MAP = new Map(AIRPORTS.map(a => [a.code.toUpperCase(), a]));

/**
 * Get airport by 3-letter IATA code.
 * Never guesses or substitutes a similar code if not found.
 */
export function getAirport(code) {
  if (!code) return null;
  const upper = String(code).trim().toUpperCase();
  return AIRPORT_MAP.get(upper) || null;
}

/**
 * Check if the airport is part of the Seoul metropolitan home base (ICN or GMP)
 */
export function isKoreaBase(code) {
  if (!code) return false;
  return KOREA_BASES.includes(String(code).trim().toUpperCase());
}

/**
 * Filter airports for search autocomplete across all global IATA airports.
 * Ranks exact IATA code match first, then code/city prefix matches, then substring matches.
 */
export function searchAirports(query, limit = 8) {
  if (!query) return [];
  const q = String(query).trim().toLowerCase();
  if (!q) return [];

  const exactCode = [];
  const prefixMatches = [];
  const substringMatches = [];

  for (const a of AIRPORTS) {
    const codeLower = a.code.toLowerCase();
    const cityLower = a.city.toLowerCase();
    const cityEnLower = (a.cityEn || '').toLowerCase();
    const countryLower = a.country.toLowerCase();
    const countryEnLower = (a.countryEn || '').toLowerCase();

    if (codeLower === q) {
      exactCode.push(a);
    } else if (codeLower.startsWith(q) || cityLower.startsWith(q) || cityEnLower.startsWith(q)) {
      if (prefixMatches.length < limit) prefixMatches.push(a);
    } else if (
      codeLower.includes(q) ||
      cityLower.includes(q) ||
      cityEnLower.includes(q) ||
      countryLower.includes(q) ||
      countryEnLower.includes(q)
    ) {
      if (substringMatches.length < limit) substringMatches.push(a);
    }
  }

  return [...exactCode, ...prefixMatches, ...substringMatches].slice(0, limit);
}
